import collections,hashlib,json,pathlib
p=pathlib.Path('private/premise-symbolic-integration');rows=[]
sha=lambda f:hashlib.file_digest(pathlib.Path(f).open('rb'),'sha256').hexdigest()
for route,comparison in [('system','comparison-configured-1'),('slice','comparison-configured-1'),('corpus','comparison-corpus-1')]:
 directory=p/'prepared-tip'/route;inv=json.loads((directory/'invocation.json').read_bytes());assert inv['exit']==0 and inv['head']==inv['head_after']=='eb0dc0cadb10e84ad6df79e36ca22996fd6ce528';assert inv['inputs_before']==inv['inputs_after'] and inv['binary_sha256']==inv['binary_sha256_after']=='775d87b7df2b8281b990abc372dd398930a79f88f71e40062058288cf873cf40'
 f=p/comparison/route/'final-comparison.json';v=json.loads(f.read_bytes());assert v['all_existing_fields_equal_after_exact_time_identity_attribution'] and v['all_fields_retained'] and not any(v['unexplained_remaining_leaf_counts'].values())
